import os
out=os.path.join(os.path.dirname(os.path.abspath(__file__)),"reconstruction.csv")  # path made relative when archived; content untouched
with open(out,"w",newline="",encoding="utf-8") as f:
    w=csv.writer(f)
    w.writerow("section,field_name,procedure_tier,analysis_tier,keyed_by,eds_point,eds_mapping,wds_point,wds_mapping,evidence,confidence,ambiguity_note".split(","))
    for s,n,p,a,k,m,e,c,amb in R:
        w.writerow([s,n,p,a,k,*m.split(),e,c,amb])
print(len(R))
